// Format message with severity
const body = $input.first().json.body || {};

const severityEmoji = {
  info: 'information_source',
  success: 'white_check_mark',
  warning: 'warning',
  error: 'rotating_light',
  critical: 'fire'
};

const severity = body.severity || 'info';
const emoji = severityEmoji[severity] || severityEmoji.info;

return {
  json: {
    channel: body.channel || '#bd-alerts',
    message: body.message || 'No message provided',
    severity: severity,
    emoji: emoji,
    formatted_message: `:${emoji}: *[${severity.toUpperCase()}]* ${body.message || 'No message provided'}`,
    timestamp: new Date().toISOString()
  }
};

// Return response (Slack node disabled - configure credentials)
const formatted = $('Format Message').first().json;

return {
  json: {
    success: true,
    message: 'Alert processed',
    details: {
      channel: formatted.channel,
      severity: formatted.severity,
      message_preview: formatted.message.substring(0, 100)
    },
    note: 'Slack node disabled - configure OAuth2 credentials',
    timestamp: formatted.timestamp
  }
};
